use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = mill.stock.inventory();
    var result = "";
    var first = true;
    var i = 0;
    while i < planks.length() {
        let plank = planks.at(i);
        if mill.rules.keep(plank) {
            if !first {
                result = result.concat(other: ",");
            }
            result = result.concat(other: mill.rules.label(plank));
            first = false;
        }
        i = i + 1;
    }
    result
}

