fn entries() -> String {
    let signals = harbor.signal.signals();
    var out = "";
    var i = 0;
    while i < signals.length() {
        if i > 0 {
            out = out.concat(other: ";");
        }
        let rendered = match signals[i] {
            Signal.Calm => "calm",
            Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            Signal.Fog(density) => "fog:".concat(other: density),
        };
        out = out.concat(other: rendered);
        i = i + 1;
    }
    out
}

