use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.get_board();
    let dishes = board.dishes();
    let count = dishes.length();

    var i = 0;
    while i < count {
        let dish = dishes.get(index: i)?;
        kitchen.serve(dish: dish)?;

        if i + 1 < count {
            io.write(text: ";")?;
        }
        i = i + 1;
    }

    return Ok(unit);
}

