}

use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in relay.feed.frames() {
        total = total + match relay.feed.decode(frame: frame) {
            Some(value) => value,
            None => 0,
        };
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

