    var total = 0;
    var i = 0;
    while i < frames.len() {
        total = total + match relay.feed.decode(frame: frames.get(index: i)) {
            Ok(value) => value,
            Err(_) => 0,
        };
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

